{"code":"function solve(text, pattern) {
  const n = text.length, m = pattern.length;
  let prev = new Array(m + 1).fill(false);
  prev[0] = true;
  for (let j = 1; j <= m; j++) prev[j] = prev[j - 1] && pattern[j - 1] === '*';
  for (let i = 1; i <= n; i++) {
    const cur = new Array(m + 1).fill(false);
    for (let j = 1; j <= m; j++) {
      const p = pattern[j - 1];
      if (p === '*') cur[j] = cur[j - 1] || prev[j];
      else cur[j] = prev[j - 1] && (p === '?' || p === text[i - 1]);
    }
    prev = cur;
  }
  return prev[m] === true;
}"}

