{"explanation":"Iteratively multiply base by itself exponent times, starting from 1. This gives 0^0=1 naturally, and all results are within safe integer range (max 5^10 = 9765625). Result of -0 is avoided: starting at 1 and multiplying by 0 gives 0, and 0 * negative could give -0, so the result is normalized by adding 0 (-0 + 0 = 0).","code":"function solve(base, exponent) {
  var result = 1;
  for (var i = 0; i < exponent; i++) {
    result *= base;
  }
  return result + 0;
}"}

{"explanation":"Empty pointer returns the document. Otherwise split on '/', skip the leading empty token, and unescape each token (~1 to / first, then ~0 to ~, in that order, via a single-pass regex so '~01' becomes '~1'). Walk the value: for arrays, the token must match canonical nonnegative integer form (0 or [1-9][0-9]*) and be within bounds; for plain objects, use Object.prototype.hasOwnProperty.call so only own properties resolve and __proto__/constructor are treated as ordinary names. Primitives and null cannot be traversed, so they yield null. Any missing step returns null. The final value is returned as-is (a JSON value, never undefined); a stored null stays null. A pointer not starting with '/' is treated as missing (null). Inputs are not mutated.","code":"function solve(document, pointer) {
  if (pointer === '') return document;
  if (typeof pointer !== 'string' || pointer.charAt(0) !== '/') return null;
  var tokens = pointer.slice(1).split('/');
  var cur = document;
  for (var i = 0; i < tokens.length; i++) {
    var tok = tokens[i].replace(/~([01])/g, function (m, d) {
      return d === '0' ? '~' : '/';
    });
    if (cur === null || typeof cur !== 'object') return null;
    if (Array.isArray(cur)) {
      if (!/^(0|[1-9][0-9]*)$/.test(tok)) return null;
      var idx = Number(tok);
      if (!(idx < cur.length)) return null;
      cur = cur[idx];
    } else {
      if (!Object.prototype.hasOwnProperty.call(cur, tok)) return null;
      cur = Object.getOwnPropertyDescriptor(cur, tok).value;
    }
    if (cur === undefined) return null;
  }
  return cur;
}"}

{"explanation":"Spreadsheet labels use bijective base-26. Repeatedly subtract 1 from n, take n % 26 as the next letter (0=A..25=Z), prepend it, then integer-divide n by 26 until n is 0. For example, 26 -> 25 -> 'Z', n=0 stops; 27 -> 26 -> 'A', n=1 -> 0 -> 'A', giving 'AA'. Only core ECMAScript is used and the input is a number, so nothing is mutated.","code":"function solve(n) {
  var letters = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
  var result = '';
  var k = n;
  while (k > 0) {
    k = k - 1;
    result = letters.charAt(k % 26) + result;
    k = Math.floor(k / 26);
  }
  return result;
}"}

{"code":"function solve(tree) {
