    }
    node = stack.pop();
    out.push(node.value);
    node = node.right;
  }
  return out;
}"}

{"explanation":"Split the path on '/', skip empty and '.' components, pop the stack on '..' (ignored when the stack is empty so traversal above root is prevented), and push every other component. Join the stack with '/' and prefix '/', which yields '/' for the root and no trailing slash otherwise. The input is only read, never mutated.","code":"function solve(path) {
  var parts = String(path).split('/');
  var stack = [];
  for (var i = 0; i < parts.length; i++) {
    var p = parts[i];
    if (p === '' || p === '.') continue;
    if (p === '..') {
      if (stack.length > 0) stack.pop();
      continue;
    }
    stack.push(p);
  }
  return '/' + stack.join('/');
}"}

{"explanation":"Walk the matrix with four boundaries (top, bottom, left, right). Traverse the top row left to right, the right column top to bottom, then the bottom row right to left and the left column bottom to top, shrinking the boundaries after each pass and checking that rows/columns remain before the reverse passes so single rows or columns are not duplicated. The input is only read, never mutated, and a new flat array is returned.","code":"function solve(matrix) {
  var result = [];
  var top = 0;
  var bottom = matrix.length - 1;
  var left = 0;
  var right = matrix[0].length - 1;
  while (top <= bottom && left <= right) {
    var i;
    for (i = left; i <= right; i++) result.push(matrix[top][i]);
    top++;
    for (i = top; i <= bottom; i++) result.push(matrix[i][right]);
    right--;
    if (top <= bottom) {
      for (i = right; i >= left; i--) result.push(matrix[bottom][i]);
      bottom--;
    }
    if (left <= right) {
      for (i = bottom; i >= top; i--) result.push(matrix[i][left]);
      left++;
    }
  }
  return result;
}"}

{"explanation":"Multiply base by itself exponent times in a loop starting from 1. This gives 0^0=1 naturally, handles negative bases by sign, and stays exact since max magnitude is 5^10 = 9765625, well within safe integer range. Inputs are not mutated. Note: for base 0 with exponent > 0 the result is 0; for negative base the loop could yield -0 only if base is -0, which is not an integer input in the domain here, but adding 0 normalizes any -0 to 0 for JSON safety.","code":"function solve(base, exponent) {
  var result = 1;
  for (var i = 0; i < exponent; i++) {
    result *= base;
  }
  return result + 0;
}"}

{"explanation":"Split the path on '/', skip empty and '.' components, pop the stack on '..' (ignored when the stack is empty so traversal above root is prevented), and push every other component. Join the stack with '/' and prefix a leading '/', which yields '/' for root and no trailing slash otherwise. The input is never mutated.","code":"function solve(path) {
  var parts = String(path).split('/');
  var stack = [];
  for (var i = 0; i < parts.length; i++) {
    var p = parts[i];
