{"explanation":"Copy the grid row by row so the input stays unchanged. Read the original color at (row, col). If it already equals the new color, return the copy. Otherwise run an iterative flood fill with an explicit stack over 4-connected neighbors. Each cell is checked against the original grid's color, and a visited array prevents revisits. Matching cells are written into the copy. This avoids recursion limits and mutation of inputs.","code":"function solve(grid, row, col, color) {
  const out = grid.map(function (r) { return r.slice(); });
  const h = grid.length;
  const w = grid[0].length;
  const target = grid[row][col];
  if (target === color) return out;
  const seen = [];
  for (let i = 0; i < h; i++) {
    seen.push(new Array(w).fill(false));
  }
  const stack = [[row, col]];
  seen[row][col] = true;
  while (stack.length > 0) {
    const p = stack.pop();
    const r = p[0];
    const c = p[1];
    out[r][c] = color;
    const dirs = [[1, 0], [-1, 0], [0, 1], [0, -1]];
    for (let k = 0; k < 4; k++) {
      const nr = r + dirs[k][0];
      const nc = c + dirs[k][1];
      if (nr >= 0 && nr < h && nc >= 0 && nc < w && !seen[nr][nc] && grid[nr][nc] === target) {
        seen[nr][nc] = true;
        stack.push([nr, nc]);
      }
    }
  }
  return out;
}"}

{"explanation":"Recursive deep equality over JSON values. Primitives compare with Object.is-style strictness via === (so 1 and '1' differ; JSON has no NaN). Note -0 vs 0: JSON-parsed 0 and -0 are treated as equal by ===, which is the usual structural-equality expectation. Arrays must be arrays on both sides with equal length and element-wise equality in order. Objects (non-null, non-array) compare own enumerable keys via Object.keys, requiring equal key counts and each key of a present as an own property of b (hasOwnProperty via Object.prototype.hasOwnProperty.call, so no prototype traversal) with equal values; key order is ignored. null is handled separately since typeof null is 'object'. Inputs are never mutated.","code":"function solve(a, b) {
  var has = Object.prototype.hasOwnProperty;
  function eq(x, y) {
    if (x === y) return true;
    if (typeof x !== 'object' || typeof y !== 'object') return false;
    if (x === null || y === null) return false;
    var ax = Array.isArray(x), ay = Array.isArray(y);
    if (ax !== ay) return false;
    if (ax) {
      if (x.length !== y.length) return false;
      for (var i = 0; i < x.length; i++) {
        if (!eq(x[i], y[i])) return false;
      }
      return true;
    }
    var kx = Object.keys(x), ky = Object.keys(y);
    if (kx.length !== ky.length) return false;
    for (var j = 0; j < kx.length; j++) {
      var k = kx[j];
      if (!has.call(y, k)) return false;
      if (!eq(x[k], y[k])) return false;
    }
    return true;
  }
  return eq(a, b) === true;
}"}

{"explanation":"Expand around each of the 2n-1 centers (odd and even). Track the best start and length, updating only when a strictly longer palindrome is found, so the leftmost wins ties. Empty input returns an empty string. Case-sensitive, all characters count. The input is never mutated.","code":"function solve(text) {
  var s = typeof text === 'string' ? text : '';
  var n = s.length;
  if (n === 0) return '';
  var bestStart = 0;
  var bestLen = 1;
  for (var c = 0; c < n; c++) {
    for (var k = 0; k < 2; k++) {
      var l = c;
      var r = c + k;
      while (l >= 0 && r < n && s.charAt(l) === s.charAt(r)) {
        l--;
        r++;
      }
      var len = r - l - 1;
      var start = l + 1;
      if (len > bestLen || (len === bestLen && start < bestStart)) {
        bestLen = len;
        bestStart = start;
      }
    }
  }
  return s.substring(bestStart, bestStart + bestLen);
}"}

{"code":"function solve(hour, minute) {
  const h = (hour % 12) * 30 + minute * 0.5;
  const m = minute * 6;
  const d = Math.abs(h - m);
  return Math.min(d, 360 - d);
}"}

{"code":"function solve(n, k) {
  let r = 0;
  for (let i = 2; i <= n; i++) r = (r + k) % i;
  return r;
}"}

{"explanation":"Coerce n to an unsigned 32-bit integer with n >>> 0, then use the standard SWAR popcount with Math.imul so every intermediate stays within 32-bit arithmetic. Pair counts are summed first, then nibble counts, then the multiply by 0x01010101 gathers the byte sums into the top byte, which is extracted with >>> 24. The result is a plain Number from 0 to 32.","code":"function solve(n) {
  var x = n >>> 0;
  x = x - ((x >>> 1) & 0x55555555);
  x = (x & 0x33333333) + ((x >>> 2) & 0x33333333);
  x = (x + (x >>> 4)) & 0x0f0f0f0f;
  return Math.imul(x, 0x01010101) >>> 24;
}"}

{"explanation":"Iterate over indices 0..a.length-1 and count positions where a.charCodeAt(i) differs from b.charCodeAt(i). Inputs are equal-length ASCII strings, so a simple loop suffices; no mutation and only core ECMAScript is used. The result is a plain Number.","code":"function solve(a, b) {
  var count = 0;
  var n = a.length;
  for (var i = 0; i < n; i++) {
    if (a.charCodeAt(i) !== b.charCodeAt(i)) {
      count++;
    }
  }
  return count;
}"}

{"code":"function solve(n) {
  if (n === 0) return 0;
  return 1 + (n - 1) % 9;
}"}

{"explanation":"Return '' for an empty array. Otherwise take the first string as the candidate prefix and shrink it to the common prefix with each following string by comparing characters from the start. Stop early if the prefix becomes empty. Inputs are only read, never mutated, and the result is always a string.","code":"function solve(strings) {
  if (!Array.isArray(strings) || strings.length === 0) return '';
  var prefix = String(strings[0]);
  for (var i = 1; i < strings.length && prefix.length > 0; i++) {
    var s = String(strings[i]);
    var j = 0;
    var max = Math.min(prefix.length, s.length);
    while (j < max && prefix.charCodeAt(j) === s.charCodeAt(j)) j++;
    prefix = prefix.slice(0, j);
  }
  return prefix;
}"}
